mapper.select:
SELECT COUNT(*) FROM organization
WHERE tenant_id = #{tenantId}
  AND organization_code = #{code}
  AND deleted = 0
  AND id != #{excludeId}

mapper.update:
UPDATE organization
SET deleted = 1, status = 0, updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND version = #{version}
  AND deleted = 0

