WHERE tenant_id = #{tenantId}
  AND category_id = #{categoryId}
  AND attribute_code = #{code}
  AND deleted = 0
  AND id != #{excludeId}

SELECT id FROM equipment_attribute_definition
WHERE tenant_id = #{tenantId}
  AND category_id = #{categoryId}
  AND attribute_code = #{code}
  AND deleted = 0
LIMIT 1

mapper.update:
UPDATE equipment_attribute_definition
SET deleted = 1, status = 0, updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND version = #{version}
  AND deleted = 0
